"""Original peripheral-neuropathy chapter: GBS, CIDP and MMN."""
from qbank_authoring import question,ref,finalize
GB=ref('EAN/PNS 2023 Guillain–Barré Syndrome Guideline','https://doi.org/10.1111/ene.16073')
